                editorCpuMs.push_back(milliseconds(editorCpuEnd - hostFrameStart));
                bgfxFrameCallMs.push_back(milliseconds(hostFrameEnd - bgfxFrameCallStart));
                frameDrawCalls.push_back(frameStats ? double(frameStats->numDraw) : 0.0);
