                    for (std::size_t index = 0; index < scene3dPrepareMs.size(); ++index)
                        scene3dCpuMs.push_back(scene3dPrepareMs[index] + scene3dSubmitMs[index]);

                    PROCESS_MEMORY_COUNTERS_EX memory{};
